package com.example.leavemanagement.integration;
import com.example.leavemanagement.audit.persistence.*;import com.example.leavemanagement.policy.application.*;import com.example.leavemanagement.policy.persistence.*;import com.example.leavemanagement.shared.api.DomainException;import com.example.leavemanagement.shared.security.*;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class HolidayAdministrationTest {private final CompanyHolidayRepository holidays=mock(CompanyHolidayRepository.class);private final AuditEventRepository audits=mock(AuditEventRepository.class);private final CurrentActorProvider actors=mock(CurrentActorProvider.class);private final HolidayAdministrationService service=new HolidayAdministrationService(holidays,audits,actors);private final UUID admin=UUID.randomUUID();@BeforeEach void setup(){when(actors.require()).thenReturn(new CurrentActor(admin,UUID.randomUUID(),null,Set.of("ADMINISTRATOR"),"Admin"));}@Test void deactivationPreservesRecordAndAudits(){var h=CompanyHolidayEntity.create(UUID.randomUUID(),LocalDate.of(2026,12,25),"Holiday",true,Instant.now());when(holidays.findById(h.getId())).thenReturn(Optional.of(h));var view=service.update(h.getId(),new HolidayAdministrationService.Update(h.getDate(),h.getName(),false,0));assertThat(view.active()).isFalse();verify(audits).save(any());}@Test void staleHolidayHasNoMutation(){var h=CompanyHolidayEntity.create(UUID.randomUUID(),LocalDate.now(),"Holiday",true,Instant.now());when(holidays.findById(h.getId())).thenReturn(Optional.of(h));assertThatThrownBy(()->service.update(h.getId(),new HolidayAdministrationService.Update(h.getDate(),h.getName(),false,2))).isInstanceOf(DomainException.class);verifyNoInteractions(audits);}}
